import type { LearnedSkillsSnapshotResult } from "@copilotkit/runtime/v2";

// Synthetic published snapshots with a supporting file; hashes/ZIP manifest use the SDK contract.
const fixtures = {
  r1: {
    bytes:
      "",
    etag: '"f55bf4093ffccaad6b58d7914f4828c08a2b469ca4fa389f7e71ce842dbd049a"',
  },
  r2: {
    bytes:
      "",
    etag: '"43596e2063129f93c5484967d338ccd6a9705f9b8ca228714e579746e389e621"',
  },
};
export function skillSnapshot(
  revision: "r1" | "r2" = "r1",
): LearnedSkillsSnapshotResult {
  const fixture = fixtures[revision];
  return {
    status: "snapshot",
    bytes: Uint8Array.from(Buffer.from(fixture.bytes, "base64")),
    revision,
    etag: fixture.etag,
    contentType: "application/zip",
  };
}
